import re

def extract_emails(text):
    """Extracts all valid email addresses from the text."""
    email_pattern = r'[a-zA-Z0-9_.+%-]+@[a-zA-Z0-9.-]+\.[a-zA-Z]{2,}'  # Fix: added dot and plus to local part
    return re.findall(email_pattern, text)

# Bug: previous regex '[\w]+@[\w]+\.[\w]+' missed emails like 'john.doe+test@example.com'

def fetch_value(d, key):
    try:
        return d[key]
    except Exception:
        return None
    except KeyError:
        return "Missing key"

**Bug**: The except Exception block will catch KeyError (subclass of Exception), so the except KeyError block is unreachable.
**Failing input**: fetch_value({}, 'missing')
**Fix**: Catch KeyError before Exception.

Corrected code:
```python
def fetch_value(d, key):
    try:
        return d[key]
    except KeyError:
        return "Missing key"
    except Exception:
        return None
```

