def max_element(lst):
    if not lst:
        return None
    maximum = lst[0]
    for num in lst[1:]:
        if num > maximum:
            maximum = num
    return maximum

# Bug Explanation:
# A buggy version might initialize maximum = 0,
# causing wrong result for lists containing all negative numbers.
# Test example: max_element([-3, -10, -1]) should return -1, but returns 0.

# Minimal fix: initialize maximum to lst[0] instead of 0.

def remove_keys(d):
    for k in d:
        if k.startswith('a'):
            del d[k]
    return d

**Bug**: Deleting keys from a dictionary while iterating over it raises RuntimeError: dictionary changed size during iteration.
**Failing input**: {'a1': 1, 'b2': 2, 'a3': 3}
**Fix**: Iterate over a list of keys rather than the dictionary view directly.
Example fix:
    for k in list(d.keys()):
        if k.startswith('a'):
            del d[k]
    return d

def flatten(lst):
    flat = []
    for item in lst:
        if isinstance(item, list):
            flat.extend(item)
        else:
            flat.append(item)
    return flat

# Bug Explanation:
# A buggy version might use append instead of extend when encountering a list,
# making nested lists appear as a single element list within the result.
# Test input: [1, [2, 3], 4], expected [1, 2, 3, 4], got [1, [2, 3], 4].

# Minimal fix: replace append with extend for nested lists.

class BankAccount:
    def __init__(self, balance=0):
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount

    def withdraw(self, amount):
        """Withdraw amount if sufficient balance, else raise ValueError."""
        if amount > self.balance:
            raise ValueError('Insufficient funds')
        self.balance -= amount

# Bug explanation:
# Original withdraw did not check balance, allowing negative balance.
# Failing test: withdraw(100) from balance=50 reduces balance to -50.

# Minimal fix: add balance check and raise exception.

def reverse_string(s, idx=0):
    if idx > len(s):
        return ''
    return reverse_string(s, idx + 1) + s[idx]

def find_target_range(nums, target):
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid
        elif nums[mid] > target:
            right = mid - 1
        else:
            start = mid
            end = mid
            while start > 0 and nums[start - 1] == target:
                start -= 1
            while end < len(nums) - 1 and nums[end + 1] == target:
                end += 1
            return (start, end)
    return (-1, -1)

def open_and_process(filename):
    try:
        f = open(filename, 'r')
        data = f.read()
        num = int(data)
    except:
        print("Failed to open or parse file")
    else:
        print(f"Read number: {num}")
    finally:
        f.close()

class Logger:
    logs = {}

    def log(self, level, message):
        if level not in self.logs:
            self.logs[level] = []
        self.logs[level].append(message)

    def get_logs(self, level):
        return self.logs.get(level, [])

logger1 = Logger()
logger2 = Logger()
logger1.log('info', 'First info')
logger2.log('info', 'Second info')
print(logger1.get_logs('info'))  # Expect ['First info']
print(logger2.get_logs('info'))  # Expect ['Second info']

**Bug**: The `logs` dictionary is a class variable, shared among instances. Logging from any instance adds entries to the same shared dictionary. This violates instance encapsulation.

**Failing input**: Logs added via one instance appear in another instance's logs:
```python
logger1 = Logger()
logger2 = Logger()
logger1.log('info', 'First info')
logger2.log('info', 'Second info')
print(logger1.get_logs('info'))  # Outputs ['First info', 'Second info']
print(logger2.get_logs('info'))  # Outputs ['First info', 'Second info']
```

**Fix**: Initialize `self.logs` as an empty dictionary per instance:
```python
class Logger:
    def __init__(self):
        self.logs = {}

    def log(self, level, message):
        if level not in self.logs:
            self.logs[level] = []
        self.logs[level].append(message)

    def get_logs(self, level):
        return self.logs.get(level, [])
```
